2	-- 20260420000017_add_app_id_to_legacy_tables.sql
3	--
4	-- Adds app_id to all 34 legacy tables that were created before the BUBS
5	-- multi-app architecture. Backfills existing rows with the Rankora app UUID,
6	-- replaces weak/open RLS policies with proper is_account_member() +
7	-- has_app_access() checks matching the rankora_* table convention.
8	-- ============================================================================
9	
10	-- ────────────────────────────────────────────────────────────────────────────
11	-- PART 1: Add app_id column + backfill + NOT NULL
12	-- ────────────────────────────────────────────────────────────────────────────
13	
14	-- Helper: wrap repeated ALTER + UPDATE + SET NOT NULL in a DO block
15	-- so the migration is idempotent (safe to re-run if partially applied).
16	
17	DO $add_app_id$
18	DECLARE
19	  v_app_id uuid := get_app_id('rankora');
20	  tbl text;
21	BEGIN
22	  IF v_app_id IS NULL THEN
23	    RAISE EXCEPTION 'Rankora app not found in apps table — cannot backfill app_id';
24	  END IF;
25	
26	  -- ── Category 1: tables with account_id ──────────────────────────────────
27	  FOREACH tbl IN ARRAY ARRAY[
28	    'activity_log',
29	    'agency_clients',
30	    'agency_commissions',
31	    'agency_communications',
32	    'agency_contacts',
33	    'agency_invoices',
34	    'agency_mandates',
35	    'agency_placements',
36	    'availability_slots',
37	    'guest_links',
38	    'hire_outcomes',
39	    'interviews',
40	    'notifications',
41	    'outreach_history',
42	    'payments',
43	    'scorecard_responses',
44	    'scorecard_templates',
45	    'sequences',
46	    'stage_tracker',
47	    'talent_pool',
48	    'talent_pool_members',
49	    'team_invitations',
50	    'webhook_configs'
51	  ]
52	  LOOP
53	    IF NOT EXISTS (
54	      SELECT 1 FROM information_schema.columns
55	      WHERE table_schema = 'public' AND table_name = tbl AND column_name = 'app_id'
56	    ) THEN
57	      EXECUTE format('ALTER TABLE %I ADD COLUMN app_id uuid REFERENCES apps(id)', tbl);
58	      EXECUTE format('UPDATE %I SET app_id = $1 WHERE app_id IS NULL', tbl) USING v_app_id;
59	      EXECUTE format('ALTER TABLE %I ALTER COLUMN app_id SET NOT NULL', tbl);
60	    END IF;
61	  END LOOP;
62	
63	  -- ── Category 2: tables connected via FK chain ───────────────────────────
64	  FOREACH tbl IN ARRAY ARRAY[
65	    'booking_tokens',
66	    'candidate_stages',
67	    'career_subscribers',
68	    'job_form_fields',
69	    'job_views',
70	    'outreach_log',
71	    'sequence_enrollments',
72	    'sequence_steps',
73	    'stage_automations',
74	    'stage_history',
75	    'sms_logs'
76	  ]
77	  LOOP
78	    IF NOT EXISTS (
79	      SELECT 1 FROM information_schema.columns
80	      WHERE table_schema = 'public' AND table_name = tbl AND column_name = 'app_id'
81	    ) THEN
82	      EXECUTE format('ALTER TABLE %I ADD COLUMN app_id uuid REFERENCES apps(id)', tbl);
83	      EXECUTE format('UPDATE %I SET app_id = $1 WHERE app_id IS NULL', tbl) USING v_app_id;
84	      EXECUTE format('ALTER TABLE %I ALTER COLUMN app_id SET NOT NULL', tbl);
85	    END IF;
86	  END LOOP;
87	END $add_app_id$;
